-- Кейсы Polza с публичного сайта polzaagency.ru/cases (предложение CEO 23.09.2026).
--
-- Кейс, опубликованный на сайте, уже согласован с клиентом для публичного
-- показа, поэтому чистые кейсы заводятся сразу утверждёнными
-- (status='approved', legal_publication_approved=true). Спорные — черновиками
-- с причиной в notes: дубли цифр, NDA, слабые или противоречивые результаты.
-- Тексты составлены по странице, цифры и сроки — дословно (source_location
-- хранит фрагмент страницы с цифрами).
--
-- Английские поля нужны английскому автоаутричу; колонки создаются и здесь,
-- чтобы миграция не зависела от порядка слияния веток.

alter table public.polza_ru_cases
  add column if not exists case_text_en text,
  add column if not exists case_segment_en text,
  add column if not exists case_url text;

-- Черновики из базы знаний, у которых есть версия на сайте, заменяются ею.
delete from public.polza_ru_cases
where case_id in ('kkzsk', 'uremont', 'drink_and_eat', 'victory_group') and status = 'draft';

insert into public.polza_ru_cases
  (case_id, public_name, industry_groups, case_text_short, case_text_en, case_segment_en, case_url,
   source_file_or_url, source_location, status, legal_publication_approved, verified_at, verified_by, notes)
values
  ('3d_printer', '3D-принтер', '{manufacturing}', 'для поставщика 3D-принтеров для рекламных производств собрали базу через 2ГИС и Яндекс.Карты — 26 лидов при 15,1% ответов за 3 месяца.', 'a 3D printer supplier get 26 leads with a 15.1% reply rate in 3 months', 'industrial equipment supply', 'https://polzaagency.ru/cases/3d-printer', 'https://polzaagency.ru/cases/3d-printer', '3D-принтер: 26 лидов из 2 733 контактов через 2ГИС | 3 мес. срок | 15.1% Reply Rate | Div3D 2ГИС + Яндекс.Карты — 15.1% reply', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Клиент — поставщик (не производитель) 3D-принтеров; публичное имя обезличено («3D-принтер», в кампании мелькает Div3D). На странице также «Конверсия в сделку — 15%» без абсолютных чисел.'),
  ('adk_trans', 'АДК Транс', '{auto_logistics}', 'для B2B-грузоперевозчика АДК Транс провели две волны email-аутрича — 179 лидов и 5 продаж.', 'a B2B freight carrier get 179 leads and 5 sales across two email outreach waves', 'B2B freight logistics', 'https://polzaagency.ru/cases/adk-trans', 'https://polzaagency.ru/cases/adk-trans', 'По итогам двух email-волн мы получили 179 лидов и 5 продаж. Первая email-волна дала 54 лида, вторая — еще 125.', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Общий период не указан; есть только период второй волны 30.06.2026–24.08.2026 (125 лидов). Reply rate не указан. 61 357 контактов, 190 402 писем.'),
  ('appevent', 'AppEvent', '{it_saas}', 'для event-tech платформы AppEvent собрали базу HR и event-менеджеров — 11 лидов при 2,1% ответов за 6 месяцев.', 'an event management SaaS platform get 11 leads with a 2.1% reply rate in 6 months', 'event tech SaaS', 'https://polzaagency.ru/cases/appevent', 'https://polzaagency.ru/cases/appevent', 'AppEvent: 11 лидов из базы 8 122 контакта | 6 мес. срок | 2.1% Reply Rate', 'draft', false, null, null, 'С сайта polzaagency.ru 23.09.2026. ответов ниже нормы; лиды пришли не из целевого сегмента Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Противоречие на странице: таргет — HR/event-менеджеры компаний 200+, но шаг «11 лидов из спортивного сегмента» (спортшколы, детские центры). Reply 2,1% ниже заявленной на сайте «нормы 3–5%».'),
  ('beautylizer', 'Beautylizer', '{manufacturing}', 'для производителя аппаратов коррекции фигуры Beautylizer вышли на салоны, SPA и клиники — 75 лидов при 8% ответов за 4 месяца.', 'a beauty equipment manufacturer get 75 leads with an 8% reply rate in 4 months', 'beauty equipment manufacturing', 'https://polzaagency.ru/cases/beautylizer', 'https://polzaagency.ru/cases/beautylizer', 'Beautylizer: 75 лидов за 5 939 контактов, 5 кампаний | 4 мес. срок | 8% Reply Rate', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок».'),
  ('bero_pro', 'Bero.pro', '{it_saas}', 'для команды заказной разработки Bero.pro проверили несколько источников и сегментов — 30 лидов за два месяца и сделка на 10,8 млн ₽.', 'a custom software development team get 30 leads in two months, one of which grew into a 10.8M RUB deal', 'custom software development', 'https://polzaagency.ru/cases/bero-pro', 'https://polzaagency.ru/cases/bero-pro', 'За два месяца мы передали Bero.pro 30 лидов на разработку и автоматизацию. Один из диалогов завершился сделкой на 10,8 млн ₽ при бюджете кампании 300 тыс. ₽.', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Reply rate не указан. 10,8 млн ₽ — стоимость проекта клиента, не выручка агентства.'),
  ('bpmsoft', 'BPMSoft', '{it_saas}', 'для CRM и low-code платформы BPMSoft привлекали enterprise-аудиторию на вебинар — 3 регистрации из 6 293 контактов за 1 месяц.', 'a CRM and low-code platform get 3 webinar registrations from 6,293 enterprise contacts in 1 month', 'enterprise CRM software', 'https://polzaagency.ru/cases/bpmsoft', 'https://polzaagency.ru/cases/bpmsoft', 'BPMSoft: 3 регистрации из 6 293 enterprise-контактов | 1 мес. срок | BPMSoft солянка от 1,5 млрд — 3 регистрации в финальном отчёте', 'draft', false, null, null, 'С сайта polzaagency.ru 23.09.2026. слабый результат (3 регистрации, 0,4% ответов) — в офферах лучше не использовать Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Результат — регистрации на вебинар, а не лиды на продукт. Reply 0,4%, open 26% — слабый кейс, в оффер лучше не брать.'),
  ('brosto', 'Brosto.pro', '{digital_agency}', 'для SEO-агентства медицинских клиник Brosto.pro собрали базу клиник через 2ГИС — 16 лидов при 2,5% ответов и 74% открытий за 4 месяца.', 'a healthcare SEO agency get 16 leads with a 74% open rate in 4 months', 'healthcare marketing agency', 'https://polzaagency.ru/cases/brosto', 'https://polzaagency.ru/cases/brosto', 'Brosto.pro: 16 лидов из 3 173 контактов, open 74% | 4 мес. срок | 74% Open Rate | 2.5% Reply Rate', 'draft', false, null, null, 'С сайта polzaagency.ru 23.09.2026. ответов ниже нормы Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Reply 2,5% ниже «нормы 3–5%», поэтому в EN-версии акцент на open rate.'),
  ('deaz', 'NDA', '{it_saas}', 'для платформы автоматизации креативного продакшна (клиент под NDA) вышли на рекламные и performance-агентства — 13 лидов при 3,6% ответов за 1 месяц.', 'a creative automation platform get 13 leads with a 3.6% reply rate in 1 month', 'MarTech SaaS', 'https://polzaagency.ru/cases/deaz', 'https://polzaagency.ru/cases/deaz', 'NDA: 13 лидов за 2 742 контакта, 7 кампаний | 1 мес. срок | 3,6% Reply Rate', 'draft', false, null, null, 'С сайта polzaagency.ru 23.09.2026. клиент под NDA — без названия, уточнить, можно ли упоминать Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Клиент под NDA: имя на странице не раскрыто (slug deaz), public_name = «NDA».'),
  ('drink_and_eat', 'Drink-and-eat', '{horeca}', 'для производителя съедобных стаканчиков Drink-and-eat запустили 22 кампании по сегментам HoReCa — 181 лид при 8,5% ответов за 4 месяца.', 'an edible cup manufacturer get 181 leads from cafes and restaurants with an 8.5% reply rate in 4 months', 'HoReCa packaging', 'https://polzaagency.ru/cases/drink-and-eat', 'https://polzaagency.ru/cases/drink-and-eat', 'Drink-and-eat: 181 лид за 13 662 контакта, 22 кампании | 4 мес. срок | 8,5% Reply Rate', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Клиент — производитель упаковки; horeca выбрана по целевой аудитории и метке страницы «HoReCa» (альтернатива — manufacturing).'),
  ('gate', 'PR-агентство Gate', '{digital_agency}', 'для PR-агентства Gate собрали базу IT-директоров по маркетингу через HH — 8 лидов при 8,9% ответов за 2 месяца.', 'a PR agency for IT companies get 8 leads with an 8.9% reply rate in 2 months', 'PR agency', 'https://polzaagency.ru/cases/gate', 'https://polzaagency.ru/cases/gate', 'PR-агентство Gate: 8 лидов из 2 009 IT-директоров маркетинга | 2 мес. срок | 8.9% Reply Rate | HH IT директор по маркетингу — 8.9% reply', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». 8,9% указано и как общий reply, и как лучшая кампания. Заявлена «конверсия из лида в договор — 21%» (при 8 лидах число не бьётся).'),
  ('general_trading', 'Дженерал Трейдинг', '{auto_logistics}', 'для оптовой торговой компании Дженерал Трейдинг вышли на закупщиков через СБИС — 5 лидов при 3,7% ответов за 2 месяца.', 'a wholesale trading company get 5 leads with a 3.7% reply rate in 2 months', 'B2B wholesale', 'https://polzaagency.ru/cases/general-trading', 'https://polzaagency.ru/cases/general-trading', 'Дженерал Трейдинг: 5 лидов из 2 700 контактов, открыто 80% | 2 мес. срок | 3.7% Reply Rate', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Также: «3 из 5 лидов сделали тестовую закупку в течение 6 недель».'),
  ('godigital', 'GoDigital', '{digital_agency}', 'для диджитал-агентства онлайн-школ GoDigital собрали точную базу EdTech через HH — 6 лидов при 9,6% ответов за 2 месяца.', 'a digital marketing agency for online schools get 6 leads with a 9.6% reply rate in 2 months', 'digital marketing agency', 'https://polzaagency.ru/cases/godigital', 'https://polzaagency.ru/cases/godigital', 'GoDigital: 6 лидов из 1 388 контактов, reply 9.6% | 2 мес. срок | HH онлайн-школы — 9.6% reply', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Также: «Два клиента перешли в работу по итогам кампании».'),
  ('hvoynyy_ostrov', 'Хвойный Остров', '{}', 'для продавца новогодних елей и оформления входных зон Хвойный Остров прошли 8 197 контактов в 13 кампаниях — 9 лидов при 7,5% ответов за 1 месяц.', 'a seasonal decor supplier get 9 leads with a 7.5% reply rate in 1 month', 'seasonal decor supply', 'https://polzaagency.ru/cases/hvoynyy-ostrov', 'https://polzaagency.ru/cases/hvoynyy-ostrov', 'Хвойный Остров: 9 лидов за 8 197 контактов, 13 кампаний | 1 мес. срок | 7,5% Reply Rate', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». industry_group = null: страница помечает «Производство», но клиент продаёт ели и оформление для бизнеса — ни одна группа точно не подходит.'),
  ('ift', 'IFT', '{auto_logistics}', 'для транспортно-логистической компании IFT запускали аутрич волнами по регионам — 10 горячих лидов при 4,2% ответов за 5 месяцев.', 'a freight logistics company get 10 hot leads with a 4.2% reply rate in 5 months', 'B2B freight logistics', 'https://polzaagency.ru/cases/ift', 'https://polzaagency.ru/cases/ift', 'IFT: 10 горячих лидов из базы 15 548 контактов | 5 мес. срок | 4.2% Reply Rate', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Страница помечает отрасль как «Производство», но клиент — логистика.'),
  ('ink_agency', 'INK Agency', '{digital_agency}', 'для агентства маркетинговых коммуникаций INK Agency вышли на директоров по маркетингу B2B-компаний — 5 лидов при 4,4% ответов за 2 месяца.', 'an integrated marketing communications agency get 5 leads with a 4.4% reply rate in 2 months', 'B2B marketing agency', 'https://polzaagency.ru/cases/ink-agency', 'https://polzaagency.ru/cases/ink-agency', 'INK Agency: 5 лидов из 2 867 контактов, открыто 82% | 2 мес. срок | 4.4% Reply Rate', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Также: «Конверсия из лида в договор составила 40%».'),
  ('inxy', 'INXY', '{it_saas}', 'для платформы международных B2B-платежей INXY вышли на компании с ВЭД в трёх международных кампаниях — 9 лидов при 2,97% ответов за 4 месяца.', 'a cross-border B2B payments platform get 9 leads with a 2.97% reply rate in 4 months', 'cross-border fintech', 'https://polzaagency.ru/cases/inxy', 'https://polzaagency.ru/cases/inxy', 'INXY: 9 лидов из 5 000 контактов, open 75% | 4 мес. срок | INXY международные платежи — 2.97% reply, 9 лидов', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». FinTech отнесён к it_saas (платёжная платформа). Reply 2,97% ниже «нормы 3–5%».'),
  ('kadry_online', 'Кадры Онлайн', '{hr_education}', 'для HR-платформы Кадры Онлайн запустили 21 кампанию на компании с IT-наймом через HH — 21 лид при ответах до 14,8% за 6 месяцев.', 'an HR automation platform get 21 leads with reply rates up to 14.8% in 6 months', 'HR tech', 'https://polzaagency.ru/cases/kadry-online', 'https://polzaagency.ru/cases/kadry-online', 'Кадры Онлайн: 21 лид, ответы до 14.8% — 21 кампания | 6 мес. срок | IT + HH бизнес-аналитики — 14.8% reply', 'draft', false, null, null, 'С сайта polzaagency.ru 23.09.2026. цифры на сайте совпадают со StormBPMN один в один — похоже на копию, сверить Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». 14,8% — лучшая кампания, не среднее. ПОДОЗРЕНИЕ: метрики совпадают со StormBPMN один в один (14 927 контактов, 21 кампания, 50% open, 14,8% reply, 6 мес., тот же сегмент «IT + HH бизнес-аналитики») — вероятна копипаста на сайте.'),
  ('kitchen_no_more', 'Kitchen No More', '{horeca}', 'для поставщика вендинговых автоматов Kitchen No More вышли на отели и офисы США на английском — 3 лида при 2% ответов за 3 месяца.', 'a US vending machine supplier get 3 leads from hotels and offices with a 2% reply rate in 3 months', 'hospitality vending', 'https://polzaagency.ru/cases/kitchen-no-more', 'https://polzaagency.ru/cases/kitchen-no-more', 'Kitchen No More: 3 лида из 1 460 контактов на рынке США | 3 мес. срок | 2% Reply Rate', 'draft', false, null, null, 'С сайта polzaagency.ru 23.09.2026. слабый результат (3 лида) Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Рынок США, англоязычный аутрич. horeca выбрана по аудитории (отели); страница помечает «B2B опт». Слабый кейс (3 лида).'),
  ('kzsk', 'КЗСК', '{manufacturing}', 'для производителя металлоконструкций КЗСК собрали базу через HeadHunter и СБИС — 24 лида за 4 месяца, лучшая кампания дала 13,6% ответов.', 'a steel structures manufacturer get 24 leads in 4 months, with a 13.6% reply rate in the best campaign', 'industrial manufacturing', 'https://polzaagency.ru/cases/kzsk', 'https://polzaagency.ru/cases/kzsk', 'КЗСК: 24 лида, best ответы 13.6% через HH | 4 мес. срок | Небольшой сегмент через HH показал 13.6% reply — лучший результат. Большая общая кампания дала 6.8%.', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». 13,6% — лучший (малый) сегмент, хотя в карточке стоит как общий Reply Rate; большая кампания дала 6,8%.'),
  ('leonteona', 'Leonteona', '{auto_logistics}', 'для оптового поставщика светотехники Leonteona запустили 11 кампаний по строительным нишам — 41 лид при 6,1% ответов за 5 месяцев.', 'a wholesale lighting distributor get 41 leads with a 6.1% reply rate in 5 months', 'B2B lighting distribution', 'https://polzaagency.ru/cases/leonteona', 'https://polzaagency.ru/cases/leonteona', 'Leonteona: 41 лид из 5 536 контактов, 11 кампаний | 5 мес. срок | 6.1% Reply Rate', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Дистрибьютор → auto_logistics (trading/distribution); альтернатива — manufacturing.'),
  ('magnumstroy', 'МагнумСтрой', '{manufacturing}', 'для производителя фасадных панелей МагнумСтрой вышли на оптовиков стройматериалов по ОКВЭД 46 — 26 лидов при 3% ответов за 3 месяца.', 'a facade panel manufacturer get 26 leads with a 3% reply rate in 3 months', 'building materials manufacturing', 'https://polzaagency.ru/cases/magnumstroy', 'https://polzaagency.ru/cases/magnumstroy', 'МагнумСтрой: 26 лидов из 2 416 контактов, open 81.5% | 3 мес. срок | 3% Reply Rate | ОКВЭД 46 оптовики — 3% reply, 81.5% open', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Open расходится: 81.5% в заголовке, 82% в карточке. Также «8 из 26 лидов ... перешли в переговоры».'),
  ('markway', 'Markway', '{digital_agency}', 'для агентства по управлению онлайн-репутацией Markway проверили отраслевые базы и офферы — 27 лидов и 374 ответа за 3,5 месяца.', 'an online reputation management agency get 27 leads and 374 replies in 3.5 months', 'reputation management agency', 'https://polzaagency.ru/cases/markway', 'https://polzaagency.ru/cases/markway', 'За 3,5 месяца мы прошли 11 549 контактов, получили 374 ответа и передали Markway 27 лидов.', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Reply rate в процентах не указан (только 374 ответа на 11 549 контактов). Дробный период 3,5 месяца.'),
  ('moreland', 'Moreland', '{auto_logistics}', 'для дистрибьютора рыбы и морепродуктов Moreland собрали базу оптовиков и HoReCa — 13 B2B-лидов при 5% ответов за 4 месяца.', 'a seafood distributor get 13 B2B leads with a 5% reply rate in 4 months', 'food distribution', 'https://polzaagency.ru/cases/moreland', 'https://polzaagency.ru/cases/moreland', 'Moreland: 13 B2B-лидов из 3 684 контактов | 4 мес. срок | 5% Reply Rate', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Open 97% выглядит завышенным. Дистрибуция → auto_logistics (альтернатива — horeca).'),
  ('nevidimka', 'Nevidimka.pro', '{digital_agency}', 'для сервиса управления репутацией Nevidimka.pro перестроили оффер на партнёрство с агентствами — 23 лида и 324 ответа за 11 недель.', 'a reputation management service get 23 leads and 324 replies in 11 weeks through a partnership offer to agencies', 'reputation management', 'https://polzaagency.ru/cases/nevidimka', 'https://polzaagency.ru/cases/nevidimka', 'За 11 недель мы прошли 4 363 контакта агентств, получили 324 ответа и передали Nevidimka.pro 23 лида.', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Reply rate в процентах не указан. Лиды — агентства-партнёры (субподряд), а не конечные клиенты.'),
  ('onescreen', 'Onescreen', '{it_saas}', 'для SaaS-аналитики маркетплейсов Onescreen собрали базу селлеров Wildberries — 13 лидов при 6,3% ответов за 3 месяца.', 'a marketplace analytics SaaS get 13 leads with a 6.3% reply rate in 3 months', 'e-commerce analytics SaaS', 'https://polzaagency.ru/cases/onescreen', 'https://polzaagency.ru/cases/onescreen', 'Onescreen: 13 лидов из 4 533 контактов, reply 6.3% | 3 мес. срок | Wildberries аналитика — 6.3% reply', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Open всего 29%. Заявлена «Конверсия в платный план — 28%» без абсолютных чисел.'),
  ('profit_gateway', 'Profit-Gateway', '{it_saas}', 'для сервиса международных платежей Profit-Gateway провели email- и Telegram-аутрич по нескольким сегментам — 95 лидов и 1 оплаченная продажа.', 'an international payments provider get 95 leads across email and Telegram and 1 paid sale', 'international payments', 'https://polzaagency.ru/cases/profit-gateway', 'https://polzaagency.ru/cases/profit-gateway', 'Мы собрали 95 лидов по двум каналам: 78 через email-аутрич и 17 в отдельном Telegram-тесте. Один лид конвертировался в оплаченную продажу.', 'draft', false, null, null, 'С сайта polzaagency.ru 23.09.2026. часть лидов (17 из 95) из Telegram, не из писем; нет срока Период не указан. Лиды из двух каналов (78 email + 17 Telegram) — для чисто email-оффера точнее 78. Ещё одна сделка «на подписании», продажей не считается. FinTech отнесён к it_saas.'),
  ('prolog', 'ПроЛог', '{auto_logistics}', 'для компании складской логистики ПроЛог провели 9 кампаний с оффером аудита складской площади — 8 лидов при 2,6% ответов за 3 месяца.', 'a warehouse equipment and logistics company get 8 leads with a 2.6% reply rate in 3 months', 'warehouse logistics', 'https://polzaagency.ru/cases/prolog', 'https://polzaagency.ru/cases/prolog', 'ПроЛог: 8 лидов за 4 757 контактов, 9 кампаний | 3 мес. срок | 2,6% Reply Rate', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Клиент поставляет стеллажи и проектирует склады — возможна и группа manufacturing; страница помечает «Логистика».'),
  ('rarematrix', 'Rarematrix', '{digital_agency}', 'для сервиса удаления негативных отзывов Rarematrix запустили англоязычный аутрич по 11 городам Европы и США — 34 лида и 164 ответа за два месяца.', 'an online reputation service get 34 leads and 164 replies across 11 US and European cities in two months', 'online reputation management', 'https://polzaagency.ru/cases/rarematrix', 'https://polzaagency.ru/cases/rarematrix', 'За два месяца мы прошли 5 642 контакта в 11 городах, получили 164 ответа и передали Rarematrix 34 лида.', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Reply rate в процентах не указан. Англоязычный рынок (США/Европа) — хорошо подходит для англ. аутрича.'),
  ('redcat', 'RedCat', '{it_saas}', 'для команды заказной разработки RedCat проверили 18 сегментов — 20,5 лида, 428 ответов и одна оплаченная продажа за три месяца.', 'a custom software development team get 20.5 leads, 428 replies and 1 confirmed sale in three months', 'custom software development', 'https://polzaagency.ru/cases/redcat', 'https://polzaagency.ru/cases/redcat', 'За три месяца мы прошли 16 259 контактов, получили 428 ответов и передали RedCat 20,5 лида. Один из переданных диалогов завершился оплатой.', 'draft', false, null, null, 'С сайта polzaagency.ru 23.09.2026. дробное «20,5 лида» — как на сайте, уточнить Дробное число лидов (20,5) — так на странице; во внешнем тексте выглядит странно. Reply rate в процентах не указан.'),
  ('reelscut', 'Reelscut', '{it_saas}', 'для AI-платформы генерации видео Reelscut вышли на маркетинговые агентства через HH — 17 лидов при 7,69% ответов за 3 месяца.', 'an AI video generation platform get 17 leads with a 7.69% reply rate in 3 months', 'AI video SaaS', 'https://polzaagency.ru/cases/reelscut', 'https://polzaagency.ru/cases/reelscut', 'Reelscut: 17 лидов из 5 290 контактов через HH-таргетинг | 3 мес. срок | 7.69% Reply Rate | НН агентства B2B — 7.69% reply', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». 7,69% — и общий reply в карточке, и лучшая кампания. Заявлено «Конверсия из демо — 30%» без абсолютных чисел.'),
  ('saas_service_management_email_outreach', 'SaaS-платформа для сервисных служб', '{it_saas}', 'для SaaS-платформы управления техподдержкой и выездным сервисом разбили аудиторию на отраслевые гипотезы — 49+ лидов в месяц, 2 продажи и ROMI около 300%.', 'a service management SaaS reach 49+ leads per month, 2 confirmed sales and ROMI of about 300%', 'service management SaaS', 'https://polzaagency.ru/cases/saas-service-management-email-outreach', 'https://polzaagency.ru/cases/saas-service-management-email-outreach', 'Целевой ориентир по SQL был 30–40 в месяц — мы вышли на 49+ лидов ежемесячно при бюджете около 150 000 рублей. Две продажи пришли из медицинских look-alike сегментов после второго письма цепочки. ROMI составил около 300% по нашему расчету.', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Клиент обезличен (имя не раскрыто). ROMI — «около 300% по нашему расчету», приблизительно. Отчётный срез 08.09.2025–12.11.2025: 20 982 контакта, 1 019 ответов, 53 лида.'),
  ('sental', 'Сентал', '{hr_education}', 'для IT-рекрутингового агентства Сентал вышли на компании с активным IT-наймом через HH — 21 лид при 4,8% ответов за 5 месяцев.', 'an IT recruitment agency get 21 leads with a 4.8% reply rate in 5 months', 'IT recruiting', 'https://polzaagency.ru/cases/sental', 'https://polzaagency.ru/cases/sental', 'Сентал: 21 лид из 6 811 контактов, open 81% | 5 мес. срок | 4.8% Reply Rate', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». На странице также «за 21 кампанию» — совпадает с числом лидов и с Кадры Онлайн/StormBPMN, возможна копипаста.'),
  ('smartica', 'Smartica.ai', '{it_saas}', 'для AI-ассистента врачей Smartica.ai вышли на частные клиники с оффером экономии времени врача — 39 лидов при 11% ответов за 1 месяц.', 'a medical AI assistant get 39 leads with an 11% reply rate in 1 month', 'healthcare AI', 'https://polzaagency.ru/cases/smartica', 'https://polzaagency.ru/cases/smartica', 'Smartica.ai: 39 лидов за 5 912 контактов, 8 кампаний | 1 мес. срок | 11% Reply Rate', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок».'),
  ('soex_gfrc', 'SOEX GFRC', '{manufacturing}', 'для производителя фасадных систем из стеклофибробетона SOEX GFRC собрали базу по НОПРИЗ, 2GIS и Rusprofile — 24 лида за 1 месяц при 3% ответов.', 'a GFRC facade systems manufacturer get 24 leads in 1 month with a 3% reply rate', 'construction materials manufacturing', 'https://polzaagency.ru/cases/soex-gfrc', 'https://polzaagency.ru/cases/soex-gfrc', 'За 1 месяц прошли 4 637 контактов, отправили 15 050 писем, получили 139 ответов и 24 лида. Open Rate — 68%, Reply Rate — 3%.', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Также: НОПРИЗ — reply 12.2%; бюджет 84 000 руб.; чек проекта 50–300 млн руб.; «около 85% лидов релевантны».'),
  ('sokol_trade', 'Сокол Трейд', '{auto_logistics}', 'для оптовой торговой компании Сокол Трейд вышли на закупщиков через HH и корпоративные сайты — 40 лидов при 9,1% ответов за 3 месяца.', 'a wholesale trading company get 40 leads with a 9.1% reply rate in 3 months', 'B2B wholesale', 'https://polzaagency.ru/cases/sokol-trade', 'https://polzaagency.ru/cases/sokol-trade', 'Сокол Трейд: 40 лидов, ответы 9.1% из 2 770 контактов | 3 мес. срок', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок».'),
  ('staffline', 'StaffLine', '{hr_education}', 'для рекрутингового агентства технических специалистов StaffLine запустили 11 кампаний по отраслям — 71 лид при 4,3% ответов за 5 месяцев.', 'a technical recruitment agency get 71 leads with a 4.3% reply rate in 5 months', 'technical recruiting', 'https://polzaagency.ru/cases/staffline', 'https://polzaagency.ru/cases/staffline', 'StaffLine: 71 лид из 5 696 контактов, 11 кампаний | 5 мес. срок | 4.3% Reply Rate | StaffLine Агропром — 4.3% reply', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». 4,3% указано и как общий reply, и как лучшая кампания (агропром).'),
  ('startexam', 'Startexam', '{hr_education}', 'для платформы онлайн-тестирования персонала Startexam вышли на L&D и HR BP через HH — 4 лида при 2% ответов за 2 месяца.', 'an employee assessment platform get 4 leads with a 2% reply rate in 2 months', 'HR assessment software', 'https://polzaagency.ru/cases/startexam', 'https://polzaagency.ru/cases/startexam', 'Startexam: 4 лида из 1 874 контактов, open 38.5% | 2 мес. срок | 2% Reply Rate', 'draft', false, null, null, 'С сайта polzaagency.ru 23.09.2026. слабый результат (4 лида) Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Open расходится: 38.5% в заголовке, 38% в карточке. Слабый кейс (4 лида, reply 2%). Группа hr_education (альтернатива — it_saas).'),
  ('stormbpmn', 'StormBPMN', '{it_saas}', 'для SaaS моделирования бизнес-процессов StormBPMN запустили 21 кампанию на бизнес-аналитиков — 8 лидов за 6 месяцев, лучшая кампания дала 14,8% ответов.', 'a BPMN process modeling SaaS get 8 leads in 6 months, with a 14.8% reply rate in the best campaign', 'B2B process software', 'https://polzaagency.ru/cases/stormbpmn', 'https://polzaagency.ru/cases/stormbpmn', 'StormBPMN: 8 лидов из 14 927 контактов за 21 кампанию | 6 мес. срок | StormBPMN IT + HH бизнес-аналитики — 14.8% reply', 'draft', false, null, null, 'С сайта polzaagency.ru 23.09.2026. цифры на сайте совпадают с «Кадры онлайн»; 8 лидов при 14,8% ответов от 14 927 контактов не сходятся Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». ПОДОЗРЕНИЕ: метрики совпадают с Кадры Онлайн (14 927 контактов, 21 кампания, 50% open, 14,8% reply, 6 мес.). 8 лидов при 14,8% reply с 14 927 контактов — неправдоподобное соотношение.'),
  ('twee', 'Twee', '{hr_education}', 'для SaaS-платформы языковых школ Twee собрали базу 2 110 школ через 2ГИС — 17 лидов при 9,2% ответов за 3 месяца.', 'a language school management SaaS get 17 leads with a 9.2% reply rate in 3 months', 'EdTech SaaS', 'https://polzaagency.ru/cases/twee', 'https://polzaagency.ru/cases/twee', 'Twee: 17 лидов, открыто 80% через 2ГИС | 3 мес. срок | 2ГИС Языковые школы РФ — 9.2% reply, 80.3% open', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Open 80% в карточке vs 80.3% в лучшей кампании. Группа hr_education по вертикали (образование); альтернатива — it_saas.'),
  ('uremont', 'Uremont', '{auto_logistics}', 'для платформы обслуживания автопарков Uremont запустили 12 кампаний с оффером про потери бюджета — 28 лидов при 9,59% ответов за 3 месяца.', 'a fleet maintenance platform get 28 leads with a 9.59% reply rate in 3 months', 'fleet management platform', 'https://polzaagency.ru/cases/uremont', 'https://polzaagency.ru/cases/uremont', 'Uremont: 28 лидов за 11 535 контактов, 12 кампаний | 3 мес. срок | 9,59% Reply Rate | Кампания по ремонту и обслуживанию автопарков — 9.59% reply', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». 9,59% — и общий reply, и лучшая кампания.'),
  ('victory_group', 'Victory Group', '{digital_agency}', 'для маркетингового агентства Victory Group проверили 14 сегментов в beauty, фитнесе, медицине и девелопменте — 54 лида за шесть месяцев, четыре клиента оплатили работу.', 'a digital marketing agency get 54 leads in six months, with four clients paying for its services', 'digital marketing agency', 'https://polzaagency.ru/cases/victory-group', 'https://polzaagency.ru/cases/victory-group', 'За шесть месяцев мы прошли 16 008 контактов, получили 450 ответов и передали Victory Group 54 лида из 14 сегментов. Четыре переданных клиента оплатили работу.', 'approved', true, now(), 'polzaagency.ru/cases (публичная страница)', 'С сайта polzaagency.ru 23.09.2026.  Reply rate в процентах не указан. Ещё +3 клиента по рекомендации от одного из привлечённых (косвенный результат, не включён).'),
  ('x10_agency', 'X10 Agency', '{digital_agency}', 'для маркетингового агентства Web3-проектов X10 Agency собрали точную базу из 419 контактов — 8 лидов при 3,8% ответов за 1 месяц.', 'a Web3 marketing agency get 8 leads with a 3.8% reply rate in 1 month from 419 contacts', 'Web3 marketing agency', 'https://polzaagency.ru/cases/x10-agency', 'https://polzaagency.ru/cases/x10-agency', 'X10 Agency: 8 лидов из 419 контактов, reply 3.8% | 1 мес. срок', 'draft', false, null, null, 'С сайта polzaagency.ru 23.09.2026. на встречи пришли 9 человек при 8 лидах — цифры противоречат Цифры взяты из карточек-метрик страницы (source_quote склеен из фрагментов через '' | ''); период — из метрики «N мес. срок». Внутреннее противоречие: 15 ответов, «9 из 15 ответивших пришли на встречу», но лидов всего 8.')
on conflict (case_id) do nothing;
